<?php
namespace Tests\Feature;
use App\Models\Admin; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AuthorizationTest extends TestCase { use RefreshDatabase; public function test_guest_admin_is_redirected_to_admin_login(): void { $this->get('/admin/4/manage?tab=payments')->assertRedirect(route('admin.login.page')); } public function test_regular_admin_cannot_access_superadmin_routes(): void { $admin=Admin::create(['name'=>'Admin','email'=>'admin@test.local','password'=>'secret','status'=>'active']); $this->actingAs($admin,'admin')->get('/superadmin/global-users')->assertRedirect(route('superadmin.login.page')); } public function test_superadmin_can_access_superadmin_routes(): void { $superadmin=$this->createSuperadmin(['name'=>'Root','email'=>'root@test.local','password'=>'secret','status'=>'active']); $this->actingAs($superadmin,'superadmin')->get('/superadmin/global-users')->assertOk(); } }
